          {phones.map((phone, i) => (
            <span key={phone}>
              <a className={styles.phone} href={`tel:${phone}`}>
                {phone}
              </a>
              {i < phones.length - 1 && (
                <span className={styles.separator}> | </span>
              )}
            </span>
          ))}
          <SocialMedia />
        </div>
      </div>
    </header>
  );
};

