18	  [dateKey: string]: Record<string, PrayerDetail>;
19	}
20	
21	// ---- constants ----
22	
23	const DAY_ABBR = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
24	const MONTH_ABBR = [
25	  "Jan", "Feb", "Mar", "Apr", "May", "Jun",
26	  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
27	];
28	const PRAYERS = ["Fajr", "Sunrise", "Dhuhr", "Asr", "Magrib", "Isha"];
29	
30	// ---- helpers ----
31	
32	function ordinal(n: number): string {
33	  const s = n.toString();
34	  const last = s[s.length - 1];
35	  const last2 = s.slice(-2);
36	  if (last2 === "11" || last2 === "12" || last2 === "13") return s + "th";
37	  if (last === "1") return s + "st";
38	  if (last === "2") return s + "nd";
39	  if (last === "3") return s + "rd";
40	  return s + "th";
41	}
42	
43	function buildWeek(): {
44	  key: string;
45	  dayName: string;
46	  monthLabel: string;
47	  yearLabel: string;
48	}[] {
49	  const today = new Date();
50	  const days: {
51	    key: string;
52	    dayName: string;
53	    monthLabel: string;
54	    yearLabel: string;
55	  }[] = [];
56	
57	  for (let i = 0; i < 7; i++) {
58	    const d = new Date(today);
59	    d.setDate(today.getDate() + i);
60	
61	    const year = d.getFullYear().toString();
62	    const month = d.toLocaleString("en-US", { month: "long" }).toLowerCase();
63	    const day = d.getDate().toString();
64	    days.push({
65	      key: `${year}-${month}-${day}`,
66	      dayName: DAY_ABBR[d.getDay()],
67	      monthLabel: `${MONTH_ABBR[d.getMonth()]} ${ordinal(d.getDate())}`,
68	      yearLabel: year,
69	    });
70	  }
71	
72	  return days;
73	}
74	
75	// ---- page ----
76	
77	export default async function WeeklyPrayerTimes() {
78	  const currentYear = new Date().getFullYear().toString();
79	  const filePath = path.join(
80	    process.cwd(),
81	    "public",
82	    "data",
83	    `${currentYear}_prayer_times.json`,
84	  );
85	
86	  let yearlyData: YearlyPrayerData = {};
87	  try {
88	    const raw = await fs.readFile(filePath, "utf-8");
89	    yearlyData = JSON.parse(raw);
90	  } catch {
91	    return (
92	      <OverlayActivityProvider>
93	        <div style={styles.page}>
94	          <Header />
95	          <div style={styles.content}>
96	            <p style={styles.error}>
97	              Unable to load prayer times. Please try again later.
98	            </p>
99	          </div>
100	          <Footer />
101	        </div>
102	      </OverlayActivityProvider>
103	    );
104	  }
105	
106	  const week = buildWeek();
107	
108	  return (
109	    <OverlayActivityProvider>
110	      <div style={styles.page}>
111	        <Header />
112	        <div style={styles.content}>
113	          <h2 style={styles.title}>Weekly Prayer Times</h2>
114	
115	          {week.map(({ key, dayName, monthLabel, yearLabel }) => {
116	            const p = yearlyData[key];
117	            const isFriday = dayName === "Fri";
118	            return (
119	              <div key={key} style={styles.dayRow}>
120	                {/* day label — left side, 3 lines */}
121	                <div style={styles.dayLabel}>
122	                  <span style={isFriday ? styles.dayNameRed : styles.dayName}>{dayName}</span>
123	                  <span style={styles.monthLabel}>{monthLabel}</span>
124	                  <span style={styles.yearLabel}>{yearLabel}</span>
125	                </div>
126	
127	                {/* prayer boxes — flex-wrap beside the label */}
128	                <div style={styles.prayerRow}>
129	                  {PRAYERS.map((prayer) => {
130	                    const azan = p?.[prayer]?.azan || "—";
131	                    const iqamah = p?.[prayer]?.iqamah || "";
132	                    const isSunrise = prayer === "Sunrise";
133	                    const fridayDhuhr = isFriday && prayer === "Dhuhr";
134	
135	                    return (
136	                      <div key={prayer} style={styles.prayerBox}>
137	                        <span style={styles.prayerName}>{prayer}</span>
138	                        <span style={isSunrise ? styles.sunriseTime : styles.azan}>
139	                          {azan}
140	                        </span>
141	                        {iqamah ? (
142	                          <span style={fridayDhuhr ? styles.iqamahRed : styles.iqamah}>
143	                            {iqamah}
144	                          </span>
145	                        ) : (
146	                          <span style={styles.iqamahPlaceholder}>&nbsp;</span>
147	                        )}
148	                      </div>
149	                    );
150	                  })}
151	                </div>
152	              </div>
153	            );
154	          })}
155	        </div>
156	        <Footer />
157	      </div>
158	    </OverlayActivityProvider>
159	  );
160	}
161	
